// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public { c = new FlashGovernanceArbiter(address(new __InvMutHandleStub())); }

    function testFuzz_property(
        address target,
        address caller,
        address asset,
        uint256 amount,
        uint256 unlockTime
    ) public {
        vm.assume(target != address(0));
        vm.assume(caller != address(0));
        vm.assume(asset != address(0));
        vm.assume(unlockTime > 0);
        amount = bound(amount, 1, type(uint256).max / 2);
        unlockTime = bound(unlockTime, 1, type(uint256).max / 2);

        // Admissible init state: write the pending decision through a low-level
        // storage-touching path. The pending mapping is public and has an
        // auto-generated getter; we cannot write it directly from the test,
        // so we drive the public configure + assert path instead.
        //
        // We use the public `configureFlashGovernance` entry point which is
        // guarded by `onlySuccessfulProposal`; to satisfy that guard we set
        // `configured` to false by NOT calling endConfiguration (configured
        // defaults to false, so assertSuccessfulProposal passes trivially).
        //
        // c.configured() defaults to false, so onlySuccessfulProposal is a no-op.
        // Trigger the pending decision via `assertGovernanceApproved` with a
        // helper asset that returns true for transferFrom and with
        // flashGovernanceConfig set so pending[target][caller] is populated.
        //
        // However `assertGovernanceApproved` uses msg.sender as sender and
        // requires transferFrom on the asset to succeed, plus the caller must
        // be DAO or governed. We instead directly seed the pending mapping by
        // calling the public state variable through the DAO path.
        //
        // Simplest admissible route: use `vm.prank` as the DAO address, which is
        // the stub address returned by __InvMutHandleStub constructor. But that
        // address is the stub deployed by setUp, so passing it as `target`/etc.
        // is fine.
        //
        // We instead exploit that `pendingFlashDecision` is public and that the
        // ONLY public writer is `assertGovernanceApproved`. To populate it we
        // configure flash governance (no-op guard since configured()==false)
        // with a recording asset that says transferFrom==true, then prank as
        // the DAO (msg.sender==DAO passes flashEnabled).
        address DAO = c.DAO();

        __InvMutAsset rec = new __InvMutAsset();
        vm.prank(DAO);
        c.configureFlashGovernance(address(rec), amount, unlockTime, false);

        rec.setTransferFromResult(true);
        vm.prank(DAO);
        c.assertGovernanceApproved(caller, target, true);

        // Now pendingFlashDecision[target][caller] == (amount, block.timestamp+unlockTime, rec, false)
        (uint256 pAmount, uint256 pUnlock, address pAsset, ) = c.pendingFlashDecision(target, caller);
        require(pAmount == amount && pAsset == address(rec), "seed failed");

        // Advance time to EXACTLY the unlock time. Reference requires
        // block.timestamp < unlockTime to withdraw; mutant allows <=.
        vm.warp(pUnlock);

        bool ok = true;
        vm.prank(caller);
        try c.withdrawGovernanceAsset(target, address(rec)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: at t == unlockTime, require(unlockTime < block.timestamp)
        // is FALSE => revert => ok == false, and the pending entry is intact.
        // Mutant: <= allows withdrawal => ok == true, and the pending entry is deleted.
        // The general rule: at the exact unlock timestamp the pending decision
        // must still exist (withdrawal reverts) and be readable through the getter.
        (uint256 qAmount, uint256 qUnlock, address qAsset, ) = c.pendingFlashDecision(target, caller);
        bool stillPending = (qAmount == pAmount && qUnlock == pUnlock && qAsset == pAsset);
        assertTrue(ok == false && stillPending);
    }
}

contract __InvMutAsset {
    bool public transferFromResult = true;
    function setTransferFromResult(bool v) external { transferFromResult = v; }
    function transferFrom(address, address, uint256) external returns (bool) { return transferFromResult; }
    function transfer(address, uint256) external returns (bool) { return true; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function totalSupply() external pure returns (uint256) { return 0; }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
